<script setup>
import {ref,onMounted} from 'vue';import PageHeader from '../../components/student/PageHeader.vue';import {studentApi} from '../../services/studentApi'
const items=ref([]),loading=ref(true),error=ref('');onMounted(async()=>{try{const r=await studentApi.getResources();items.value=r.data?.resources||[]}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div><PageHeader title="Study Resources" subtitle="Real resources shared by your tutor."/><p v-if="loading">Loading resources...</p><p v-else-if="error" class="text-red-500">{{error}}</p><div v-else-if="!items.length" class="card p-8 text-center text-slate-500">No resources available yet. Your tutor can upload notes, PDFs or links.</div><div v-else class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4"><div v-for="r in items" :key="r.resource_id" class="card p-5"><p class="text-xs text-brand-blue">{{r.subject}} · {{r.resource_type}}</p><h3 class="font-display font-bold mt-1">{{r.resource_title}}</h3><a v-if="r.resource_link" :href="r.resource_link.startsWith('http')?r.resource_link:`http://localhost:5000${r.resource_link}`" target="_blank" class="btn grad sm mt-4 inline-block">Open Resource</a></div></div></div></template>
